import{_ as e,a,b as r}from"./chunks/ind-dsd-component.DI3Bmyu9.js";import{_ as o,o as d,c as s,ag as n}from"./chunks/framework.CxkNbRKf.js";const i="/nada-documentation/images/ind-dsd-list.png",c="/nada-documentation/images/ind-dsd-validate.png",A=JSON.parse('{"title":"Data structures","description":"","frontmatter":{},"headers":[],"relativePath":"admin-guide/web-ui/data-structures.md","filePath":"admin-guide/web-ui/data-structures.md","lastUpdated":1793155456000}'),l={name:"admin-guide/web-ui/data-structures.md"};function u(h,t,m,g,p,b){return d(),s("div",null,[...t[0]||(t[0]=[n('<h1 id="data-structures" tabindex="-1">Data structures <a class="header-anchor" href="#data-structures" aria-label="Permalink to &quot;Data structures&quot;">​</a></h1><p>A <strong>data structure definition (DSD)</strong> describes the columns of an indicator&#39;s data: the name, label, data type and <strong>role</strong> of each column, and the codelist it uses. NADA uses it to read uploaded data and to build the chart, filters, table and Data API of each indicator.</p><p>One data structure can be shared by many indicators. For the column roles, the series key and time period formats, see <a href="/nada-documentation/admin-guide/content/indicators-concepts.html#data-structure-dsd">Key concepts</a>.</p><div class="tip custom-block"><p class="custom-block-title">Using the Metadata Editor?</p><p>Create data structures in the Metadata Editor. They are sent to NADA when you publish. Use these screens to check them.</p></div><hr><h2 id="three-ways-to-create-a-data-structure" tabindex="-1">Three ways to create a data structure <a class="header-anchor" href="#three-ways-to-create-a-data-structure" aria-label="Permalink to &quot;Three ways to create a data structure&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Way</th><th>When to use it</th></tr></thead><tbody><tr><td><strong>Import JSON</strong></td><td>A data structure exported from the Metadata Editor, or written by hand or by a script. Codelists can be included.</td></tr><tr><td><strong>Import SDMX XML</strong></td><td>A structure file published by an SDMX agency (OECD, Eurostat…), in SDMX-ML 2.1. Creates the data structure and its codelists.</td></tr><tr><td><strong>Add data structure</strong></td><td>Build it column by column in NADA</td></tr></tbody></table><p>The API equivalents are <code>POST api/admin/data_structures/import_json</code> and <code>POST api/admin/data_structures/import</code>.</p><hr><h2 id="the-data-structures-list" tabindex="-1">The data structures list <a class="header-anchor" href="#the-data-structures-list" aria-label="Permalink to &quot;The data structures list&quot;">​</a></h2><p>Go to <strong>Settings → Data structures</strong>. The list shows each data structure&#39;s <strong>Title</strong>, <strong>Name</strong>, <strong>Agency</strong>, <strong>Latest version</strong>, number of <strong>Versions</strong>, number of <strong>Projects</strong> (indicators) that use it, <strong>IDNO</strong> and <strong>Status</strong>.</p><p>Click the number in <strong>Projects</strong> to see which indicators use a data structure. Check it before you change a data structure: every indicator that uses it is affected.</p><p><img src="'+i+'" alt=""></p><hr><h2 id="import-a-data-structure" tabindex="-1">Import a data structure <a class="header-anchor" href="#import-a-data-structure" aria-label="Permalink to &quot;Import a data structure&quot;">​</a></h2><h3 id="from-json" tabindex="-1">From JSON <a class="header-anchor" href="#from-json" aria-label="Permalink to &quot;From JSON&quot;">​</a></h3><ol><li>Go to <strong>Settings → Data structures</strong> and click <strong>Import JSON</strong>.</li><li>Choose the JSON file, for example <a href="https://github.com/ihsn/nada-documentation/raw/main/examples/indicators/SI.POV.DDAY_dsd.json" target="_blank" rel="noreferrer"><code>SI.POV.DDAY_dsd.json</code></a> from the indicator sample.</li><li>Leave <strong>Overwrite</strong> off, unless you want to replace the codes of codelists that already exist.</li><li>Click <strong>Import</strong>.</li></ol><p><img src="'+e+'" alt="Import DSD from JSON"></p><p>NADA shows <em>Import finished. Codelists touched: …</em> and opens the new data structure. Its status is <em>Draft</em>. A version such as <code>1.0</code> is stored as <code>1.0.0</code>; the IDNO stays as in the file.</p><p>The file creates the data structure and any codelist it includes. A codelist that already exists with the same IDNO is reused. If a data structure with the same IDNO, or the same agency, name and version, already exists, the import is rejected.</p><div class="warning custom-block"><p class="custom-block-title">Attribute codelists</p><p>Importing JSON currently keeps codelists on geography, dimension and periodicity columns only. A codelist on an attribute or measure column is left out. Attach it afterwards in the data structure&#39;s column editor.</p></div><h3 id="from-sdmx-xml" tabindex="-1">From SDMX XML <a class="header-anchor" href="#from-sdmx-xml" aria-label="Permalink to &quot;From SDMX XML&quot;">​</a></h3><ol><li>Click <strong>Import SDMX XML</strong>.</li><li>Choose the structure file (SDMX-ML 2.1).</li><li>If the file has more than one data structure, enter the one to import in <strong>Data structure id</strong>.</li><li>Turn on <strong>Overwrite existing codelists</strong> only to replace the codes of codelists that already exist.</li><li>Click <strong>Import</strong>.</li></ol><hr><h2 id="add-a-data-structure-by-hand" tabindex="-1">Add a data structure by hand <a class="header-anchor" href="#add-a-data-structure-by-hand" aria-label="Permalink to &quot;Add a data structure by hand&quot;">​</a></h2><ol><li><p>Click <strong>Add data structure</strong> and fill in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Agency</strong></td><td>The organization responsible. Default: <code>NADA</code>.</td></tr><tr><td><strong>Version</strong></td><td>Default: <code>1.0.0</code>.</td></tr><tr><td><strong>Name</strong></td><td>A short identifier, unique for the same agency and version.</td></tr><tr><td><strong>IDNO</strong></td><td>Leave it empty to generate it from agency, name and version. Indicators refer to the data structure by this IDNO.</td></tr><tr><td><strong>Title</strong></td><td>A readable title, such as <em>WDI indicators by country and year</em>.</td></tr><tr><td><strong>Status</strong>, <strong>Description</strong>, <strong>Notes</strong></td><td>Optional.</td></tr></tbody></table></li><li><p>Save. The data structure opens, with its <strong>Components</strong> (columns) on the left.</p></li></ol><p><img src="'+a+'" alt=""></p><h3 id="add-the-columns" tabindex="-1">Add the columns <a class="header-anchor" href="#add-the-columns" aria-label="Permalink to &quot;Add the columns&quot;">​</a></h3><p>For each column of the data:</p><ol><li><p>In <strong>Components</strong>, click <strong>Add</strong>.</p></li><li><p>Fill in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Name</strong></td><td>The column name, as in the data file&#39;s header row (case does not matter). Unique within the data structure. Do not start it with <code>_</code>: NADA uses such names internally.</td></tr><tr><td><strong>Label</strong></td><td>A readable label, shown in the catalog.</td></tr><tr><td><strong>Column type</strong></td><td>The column&#39;s role: <code>indicator_id</code>, <code>indicator_name</code>, <code>geography</code>, <code>time_period</code>, <code>observation_value</code>, <code>periodicity</code>, <code>dimension</code>, <code>attribute</code>, <code>measure</code> or <code>annotation</code>.</td></tr><tr><td><strong>Data type</strong></td><td><code>string</code>, <code>integer</code>, <code>float</code>, <code>double</code>, <code>date</code> or <code>boolean</code>. Optional.</td></tr><tr><td><strong>Time period format</strong></td><td>For the <code>time_period</code> column only, such as <code>YYYY</code>.</td></tr><tr><td><strong>Codelist</strong></td><td>For coded columns (geography, periodicity, dimension, attribute, measure): search for the codelist and select it. Its codes are listed below.</td></tr></tbody></table></li><li><p>Click <strong>Create</strong>.</p></li></ol><p><img src="'+r+'" alt=""></p><p>The sample&#39;s data structure has five columns:</p><table tabindex="0"><thead><tr><th>Name</th><th>Column type</th><th>Data type</th><th>Codelist</th></tr></thead><tbody><tr><td><code>INDICATOR</code></td><td><code>indicator_id</code></td><td>string</td><td></td></tr><tr><td><code>INDICATOR_LABEL</code></td><td><code>indicator_name</code></td><td>string</td><td></td></tr><tr><td><code>REF_AREA</code></td><td><code>geography</code></td><td>string</td><td><code>WB_CL_REF_AREA_1.0</code></td></tr><tr><td><code>YEAR</code></td><td><code>time_period</code> (<code>YYYY</code>)</td><td>string</td><td></td></tr><tr><td><code>VALUE</code></td><td><code>observation_value</code></td><td>double</td><td></td></tr></tbody></table><h3 id="validate" tabindex="-1">Validate <a class="header-anchor" href="#validate" aria-label="Permalink to &quot;Validate&quot;">​</a></h3><p>Click <strong>Validate</strong> to check the data structure. NADA shows <em>Validation passed.</em> or lists the issues. A data structure needs exactly one <code>indicator_id</code>, one <code>time_period</code> and one <code>observation_value</code> column. A <code>geography</code> column is recommended.</p><p><img src="'+c+'" alt="Validation passed"></p><p>Click <strong>Export JSON</strong> to download the data structure, for example to import it into another catalog.</p><hr><h2 id="versions-status-and-changes" tabindex="-1">Versions, status and changes <a class="header-anchor" href="#versions-status-and-changes" aria-label="Permalink to &quot;Versions, status and changes&quot;">​</a></h2><p>A data structure has a <strong>status</strong>: <em>Draft</em>, <em>Review</em>, <em>Published</em>, <em>Deprecated</em> or <em>Archived</em>. While it is <strong>Published</strong> or <strong>Archived</strong>, it is locked: its fields and columns are read-only, and only <strong>Change status</strong> is available.</p><div class="warning custom-block"><p class="custom-block-title">Changing a data structure affects every indicator that uses it</p><p>When a data structure&#39;s columns change, every indicator that uses it is marked <strong>Out of sync</strong> (sync pending). Its chart, table and Data API are hidden from the public catalog until it is resynced: open the indicator&#39;s <strong>Indicator data</strong> tab and click <strong>Resync</strong>, or upload its data again.</p></div><p>To make a larger change without affecting existing indicators, create a new version of the data structure and switch indicators to it one at a time. Switching an indicator to another data structure deletes its uploaded data, so upload the data again after switching.</p><hr><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="./codelists.html">Codelists</a></li><li><a href="/nada-documentation/admin-guide/content/indicators-admin.html">Create an indicator in NADA</a>: attach the data structure and upload data</li></ul>',45)])])}const _=o(l,[["render",u]]);export{A as __pageData,_ as default};
